/**
 * The point on an ellipse's boundary where the ray from its center toward
 * `from` exits the shape — i.e. where an arrow coming from `from` should attach.
 *
 * The ellipse is axis-aligned and inscribed in the bounding box.
 */
export function ellipseBindingPoint(box, from) {
  const c = center(box);
  const d = sub(from, c);
  if (d.x === 0 && d.y === 0) return c;
  const rx = box.w / 2;
  const ry = box.h / 2;
  const s = 1 / Math.sqrt((d.x / rx) ** 2 + (d.y / ry) ** 2);
  return add(c, scale(d, s));
}

